test('REQ-6-1#audit-1: protected branch rejects a direct file commit', async ({ page }) => {
  const repo = 'pw-repo-' + u();
  const fileName = 'blocked-' + u() + '.md';
  await signInAsAlice(page);
  await page.getByRole('link', { name: 'New repository', exact: true }).click();
  await page.getByLabel('Repository name', { exact: true }).fill(repo);
  await page.getByRole('checkbox', { name: 'Add a README file', exact: true }).check();
  await page.getByRole('button', { name: 'Create repository', exact: true }).click();
  await expect(page.getByRole('heading', { name: new RegExp(repo) })).toBeVisible();

  await page.getByRole('link', { name: 'Settings', exact: true }).click();
  await page.getByRole('link', { name: 'Branches', exact: true }).click();
  await page.getByRole('button', { name: 'Add branch protection rule', exact: true }).click();
  await page.getByLabel('Branch name pattern', { exact: true }).fill('main');
  await page.getByRole('checkbox', { name: 'Require 1 approval', exact: true }).check();
  await page.getByRole('checkbox', { name: 'Require status check test', exact: true }).check();
  await page.getByRole('button', { name: 'Create', exact: true }).click();
  await expect(page.getByText('1 approval', { exact: true })).toBeVisible();

  await page.getByRole('link', { name: 'Code', exact: true }).click();
  await page.getByRole('button', { name: 'Add file', exact: true }).click();
  await page.getByRole('menuitem', { name: 'Create new file', exact: true }).click();
  await page.getByLabel('File name', { exact: true }).fill(fileName);
  await page.getByLabel('File contents', { exact: true }).fill('should not be saved');
  await page.getByLabel('Commit message', { exact: true }).fill('attempt protected write');
  await page.getByRole('button', { name: 'Commit changes', exact: true }).click();

  await page.goto('/');
  const search = page.getByRole('searchbox', { name: 'Search', exact: true });
  await search.fill(repo);
  await search.press('Enter');
  await page.getByRole('link', { name: repo, exact: true }).click();
  await expect(page.getByRole('heading', { name: new RegExp(repo) })).toBeVisible();
  await expect(page.getByRole('link', { name: fileName, exact: true })).toHaveCount(0);
});

test('REQ-6-2-2#audit-1: Read-only signed-in user cannot start comparison flow', async ({ page }) => {
  await registerAndSignIn(page);
  await openRepository(page);
  await page.getByRole('link', { name: 'Pull requests', exact: true }).click();
  const newPr = page.getByRole('link', { name: 'New pull request', exact: true });
  if (await newPr.count()) {
    await expect(newPr).toBeDisabled();
  } else {
    await expect(newPr).toHaveCount(0);
  }
});

