test('REQ-6-2-3#audit-1: duplicate source/target pair does not create another PR', async ({ page }) => {
  const repo = 'pw-repo-' + u();
  const branch = 'feat-' + u();
  const file = 'change-' + u() + '.md';
  const firstTitle = 'pr-' + u();
  const secondTitle = 'dup-' + u();

  await signInAsAlice(page);
  await page.getByRole('link', { name: 'New repository', exact: true }).click();
  await page.getByLabel('Repository name', { exact: true }).fill(repo);
  await page.getByRole('checkbox', { name: 'Add a README file', exact: true }).check();
  await page.getByRole('button', { name: 'Create repository', exact: true }).click();
  await expect(page.getByRole('heading', { name: new RegExp(repo) })).toBeVisible();

  await page.getByRole('link', { name: 'Code', exact: true }).click();
  await page.getByRole('button', { name: 'Branch main', exact: true }).click();
  await page.getByLabel('Find branch', { exact: true }).fill(branch);
  await page.getByRole('option', { name: `Create branch: ${branch}`, exact: true }).click();
  await expect(page.getByRole('button', { name: `Branch ${branch}`, exact: true })).toBeVisible();

  await page.getByRole('button', { name: 'Add file', exact: true }).click();
  await page.getByRole('menuitem', { name: 'Create new file', exact: true }).click();
  await page.getByLabel('File name', { exact: true }).fill(file);
  await page.getByLabel('File contents', { exact: true }).fill('change');
  await page.getByLabel('Commit message', { exact: true }).fill('Add change');
  await page.getByRole('button', { name: 'Commit changes', exact: true }).click();

  await page.goto('/');
  const search = page.getByRole('searchbox', { name: 'Search', exact: true });
  await search.fill(repo);
  await search.press('Enter');
  await page.getByRole('link', { name: repo, exact: true }).click();
  await page.getByRole('link', { name: 'Pull requests', exact: true }).click();
  await page.getByRole('link', { name: 'New pull request', exact: true }).click();
  await page.getByRole('combobox', { name: 'base', exact: true }).selectOption({ label: 'main' });
  await page.getByRole('combobox', { name: 'compare', exact: true }).selectOption({ label: branch });
  await page.getByRole('button', { name: 'Compare changes', exact: true }).click();
  await page.getByRole('button', { name: 'Create pull request', exact: true }).click();
  await page.getByLabel('Title', { exact: true }).fill(firstTitle);
  await page.getByRole('button', { name: 'Create pull request', exact: true }).click();
  await expect(page.getByRole('heading', { name: firstTitle, exact: true })).toBeVisible();

  await page.getByRole('link', { name: 'Pull requests', exact: true }).click();
  await page.getByRole('link', { name: 'New pull request', exact: true }).click();
  await page.getByRole('combobox', { name: 'base', exact: true }).selectOption({ label: 'main' });
  await page.getByRole('combobox', { name: 'compare', exact: true }).selectOption({ label: branch });
  await page.getByRole('button', { name: 'Compare changes', exact: true }).click();
  const createButton = page.getByRole('button', { name: 'Create pull request', exact: true });
  if (await createButton.isEnabled()) {
    await createButton.click();
    await page.getByLabel('Title', { exact: true }).fill(secondTitle);
    await page.getByRole('button', { name: 'Create pull request', exact: true }).click();
    await expect(page.getByRole('heading', { name: secondTitle, exact: true })).toHaveCount(0);
  } else {
    await expect(createButton).toBeDisabled();
  }

  await page.getByRole('link', { name: 'Pull requests', exact: true }).click();
  await expect(page.getByRole('link', { name: firstTitle, exact: true })).toBeVisible();
  await expect(page.getByRole('link', { name: secondTitle, exact: true })).toHaveCount(0);
